from build import put, render

def b(i,d,c,a,e,f,status='Partially addressed',kind='Methodological'):
 return dict(id=i,description=d,conditions=c,cause=a,evidence=e,kind=kind,followups=f,status=status,confidence='High within the specified evidence scope')

put('mind_error',title='Mind the Error! Detection and Localization of Instruction Errors in Vision-and-Language Navigation',authors=['Francesco Taioli','Stefano Rosa','Alberto Castellini','Lorenzo Natale','Alessio Del Bue','Alessandro Farinelli','Marco Cristani','Yiming Wang'],year=2024,venue='IROS 2024; venue verification pending',pages=['2–7'],problem='Detect whether an instruction contains an erroneous direction, room, or object reference, and localize the suspect words after a navigator has executed a trajectory. This is a diagnostic task with a fixed BEVBert navigator, rather than an online language repair policy.',method='R2RIE-CE creates paired original/corrupted instructions using direction antonyms and room/object substitutions, with ConceptNet and manual constraints for more plausible replacements. Instruction BERT embeddings use up to 80 tokens of width 768. CLIP visual features from selected trajectory views, positional embeddings, and a CLS token feed four layers of cross-attention with trajectory queries and instruction keys/values, followed by self-attention and feed-forward blocks. Binary error classification uses the CLS output; a separate token head predicts error positions. Training combines binary error cross-entropy and token localization cross-entropy. The 9,000-step AdamW run trains on all error categories without commonsense filtering; the reported checkpoint is selected by validation-unseen AUC on the commonsense all-error set. Inference consumes the completed trajectory, not just the current view.',novelty='Introduces instruction-error detection and localization as distinct from instruction underspecification in ULN and language-following diagnostics in NavNuances. It operationalizes instruction/trajectory inconsistency, but does not identify whether an inconsistency was caused by the instruction or by the fixed navigator.',results='PAPER EXPERIMENT: Table II reports AUC/average token distance of 0.58/8.13 for directions, 0.80/7.73 for rooms, 0.74/9.21 for objects, 0.91/7.34 for room plus object, and 0.94/6.14 for all errors; mean 0.79/7.71. Object localization is worse than the CLIP baseline token distance 8.76. The large all-error AUC therefore should not be presented as accurate single-word repair or strong directional-error recognition. On natural R2R-CE annotations, 25 of 1,839 instructions are flagged and eight confirmed; on RxR-CE, 118 of 3,669 are flagged and ten confirmed, including mesh-related issues. These selected-case confirmations are not an estimated corpus-wide error rate. The causal ambiguity between language error and policy error remains unresolved.',implementation='Official project and repository discovery in progress. No code or online correction result is asserted.',bottlenecks=[b('iedl-cause','A trajectory-language mismatch does not identify which input or action is wrong.','The navigator takes a wrong turn while the instruction is correct, or several substitutions leave the route semantically valid.','The detector conditions on one completed policy trajectory rather than an independent ground-truth environmental explanation.','DEDUCTION from architecture; PAPER EXPERIMENT: weak directional AUC in Table II.',['NavNuances','ULN'],'Still unresolved in the reviewed literature'),b('iedl-online','Detection does not provide an online repair policy.','A mistaken instruction must be diagnosed before a long failed rollout.','The model aggregates the completed trajectory and predicts labels, with no tested action-selection or instruction-editing loop.','METHOD: architecture and evaluation protocol.',['VLN-Trans'],'Uncertain because evidence is insufficient')],sources=[dict(url='https://intelligolabs.github.io/R2RIE-CE/',locator='Official project')],limits=['Separate supplementary cases and repository review pending. Synthetic corruption is an operational error model, not a proof that every generated sentence is false.'])

put('aiuta',title='Collaborative Instance Object Navigation: Leveraging Uncertainty-Awareness to Minimize Human-Agent Dialogues',authors=['Francesco Taioli','Edoardo Zorzi','Gianni Franchi','Alberto Castellini','Alessandro Farinelli','Marco Cristani','Yiming Wang'],year=2025,venue='ICCV 2025',pages=['3–8'],problem='Find a particular object instance in an unknown continuous HM3D scene using an initial object category and dialogue with a user who knows the exact target. The agent does not see the target image; the simulated user does. Multiple same-category distractors make ordinary ObjectNav insufficient.',method='AIUTA wraps VLFM frontier navigation, BLIP-2 value mapping, and Grounding DINO detection. At a candidate object, LLaVA-1.6 Mistral 7B generates a caption and GPT-4o proposes attribute questions. The visual model scores yes/no/unknown and normalized three-way entropy selects uncertain questions with threshold 0.75. Object-presence checks may continue exploration. A language model compares accumulated facts to user answers on a 0–10 scale: high alignment (at least 7) permits stopping, low alignment (below 5) skips the candidate, and intermediate scores trigger more questions. The method allows up to four dialogue rounds and filters uncertain attributes. CoIN contains 1,649 episodes: 831 seen categories, 359 synonyms, 459 unseen categories; at least two distractors, start distance 5–20 m, success within 0.25 m of a goal viewpoint, and 500 actions. The main navigation method uses pretrained models without task fine-tuning, but depends on a truthful target-aware user and tuned decision thresholds.',novelty='Adds instance-specific collaborative verification and uncertainty-filtered dialogue to open-vocabulary object navigation. KnowNo calibrates action sets with formal distributional coverage; AIUTA instead uses heuristic entropy and alignment scores. Its user access changes the information available relative to category-only VLFM.',results='PAPER EXPERIMENT: Table 2 seen-category SR/SPL/success-conditioned question count is 7.42/2.92/1.67; synonym 14.38/7.99/1.36; unseen 6.67/2.30/1.13. PSL has better seen SR 8.78 and OVON better synonym SR 15.88. The method performs best on unseen instances among reported baselines, but absolute success remains low. Dialogue ablation reports SR 9.21→14.47 and question count 3.57→1.68 when combining self-questioning and candidate skipping. Question count is calculated on successful episodes only, so it does not measure total failed-run burden. The 20-person human study uses 40 episodes preselected to have detectable targets; 42.5% human and simulator success cannot be generalized to all 1,649 episodes. IDK-VQA has 502 questions over 102 images with three annotators; entropy improves abstention utility relative to max probability in that benchmark, without proving calibrated uncertainty under navigation shift.',implementation='Official CoIN repository identified; source and supplementary inspection pending.',bottlenecks=[b('aiuta-verify','Uncertainty-filtered dialogue does not ensure correct instance recognition or stop decisions.','Unseen object categories, poor views, misleading visual captions, or a confident visual mistake.','Entropy measures the model score distribution and alignment is another model judgment; neither is a calibrated truth test.','PAPER EXPERIMENT: Table 2 low absolute SR; METHOD: heuristic thresholds.',['KnowNo','Explore until Confident'],'Partially addressed'),b('aiuta-cost','Reported question efficiency excludes failed episodes.','Comparing user effort when methods have different success rates.','The NQ denominator includes only successful episodes.','METRIC DEFINITION: experiments section.',['KnowNo'],'Uncertain because evidence is insufficient','Evaluation')],sources=[dict(url='https://intelligolabs.github.io/CoIN/',locator='Official ICCV project'),dict(url='https://github.com/intelligolabs/CoIN',locator='Official repository')],limits=['Supplement sections A–J and released source audit pending. Human answers are assumed truthful; no benchmark executed.'])

put('activevig',title='Active Visual Information Gathering for Vision-Language Navigation',authors=['Hanqing Wang','Wenguan Wang','Tianmin Shu','Wei Liang','Jianbing Shen'],year=2020,venue='ECCV 2020',pages=['4–14'],problem='An instruction follower can move briefly to obtain useful visual evidence before committing to its next navigation direction. This requires explicit accounting of exploratory motion, including motion that reveals an already cached view.',method='An EnvDrop-style LSTM navigator encodes panoramic ResNet-152 and orientation features into 512-dimensional visual tokens and attends to 512-dimensional instruction representations. A nested exploration policy chooses a direction or exploration STOP. An exploration LSTM and knowledge LSTM summarize newly attended neighbors, producing residual updates to candidate-direction features. Multi-step exploration may inspect several directions before the navigator acts. Late action uses cached observations and executes only necessary paths to new views in the static navigation graph. Supervised shortest-path navigation and exploration initialization precede actor-critic training. Navigation rewards use goal-distance progress and terminal rewards; exploration rewards measure change in downstream navigation reward minus a 0.1 step cost. Separate critics are used. Curriculum increases maximum exploration from one to six steps, with four selected; 176,000 speaker-generated examples augment training. Exploration at inference is physical lookahead, not a learned world-model rollout.',novelty='Learns when and where to gather new visual evidence, rather than only attending to a fixed panorama. It precedes ULN’s uncertainty-triggered physical branches and explicitly includes trajectory cost. Late action is a cache/execution optimization under a static graph, not a simulator-free imagined transition model.',results='PAPER EXPERIMENT: Table 3 unseen baseline SR/SPL/TL 0.52/0.48/10.7; naive exploration 0.54/0.16/35.7; learned one-step 0.55/0.42/13.7; four-step 0.58/0.40/20.6; six-step 0.58/0.38/23.6. Table 1 test SR increases EnvDrop 0.51→0.60 while SPL falls 0.47→0.41 and TL rises 11.7→21.6. These are reliability/efficiency tradeoffs, not metric-wise dominance. Page 14 reports exploration at 15.3% of navigation steps, correcting 65.2% of initially wrong actions but corrupting 10.7% of initially correct actions. Pre-exploration with synthetic-data fine-tuning and beam search are separate settings: the latter has TL 204.4 and SPL 0.05 despite SR 0.70.',implementation='Official Active_VLN repository pinned; source inspection and late-action supplement review pending.',bottlenecks=[b('activevig-cost','Exploration improves success while consuming motion and sometimes corrupting a correct choice.','Ambiguous landmarks or long exploration branches, especially when the initial policy action was already correct.','Information value is learned through a downstream reward proxy, while new evidence can mislead the policy and incurs physical travel.','PAPER EXPERIMENT: Table 3 and p. 14 action-change analysis.',['ULN','Meta-Explore','Explore until Confident'],'Partially addressed')],sources=[dict(url='https://github.com/HanqingWangAI/Active_VLN',locator='Official implementation')],limits=['Introduction pages, late-action supplement, and source audit pending. The printed sign convention around Eqs. 18–19 requires checking against code before interpreting optimization behavior.'])

put('ieve',title='Instance-aware Exploration-Verification-Exploitation for Instance ImageGoal Navigation',authors=['Xiaohan Lei','Min Wang','Wengang Zhou','Li Li','Houqiang Li'],year=2024,venue='CVPR 2024',pages=['3–8'],problem='Find the exact object instance shown in a goal image, using RGB-D and pose in an unknown environment. This is Instance ImageGoal Navigation, not language-conditioned route following. Camera height and field of view may differ between goal and current observation.',method='A classifier identifies the central goal-image object category. RGB-D detections are projected to point clouds, voxelized, pooled, and merged into a 2+N-channel global semantic map. DISK descriptors and LightGlue matching yield instance match count omega. Distance-dependent low/high thresholds select exploration, verification, or exploitation: weak evidence explores; ambiguous evidence approaches for a better view; sufficient matching commits to the candidate; a close poor match rejects it. A learned exploration policy emits a waypoint every ten local steps, with area-coverage and target rewards. FMM generates local motion; low-level actions include continuous linear/angular velocity, camera pitch, and stop, bounded by 35 cm translation and 60 degree rotation per frame. Training uses HM3D scenes and a constructed instance re-identification dataset. Evaluation success requires proximity within one metre and oracle visibility, with 1,000 validation episodes.',novelty='The explicit approach-to-verify stage adjusts evidence acquisition to distance-dependent instance matching quality. It separates category exploration from instance commitment instead of treating a fixed matching threshold as sufficient at all viewpoints. It does not supply a conformal or probabilistic correctness guarantee.',results='PAPER EXPERIMENT: Table 1 Mod-IIN SR/SPL 0.561/0.233 versus Swin/Mask IEVE 0.684/0.241 and InternImage version 0.702/0.252. Table 2 controlled EVE versus exploration/exploitation improves 0.590/0.221→0.666/0.235 with the same Mask classifier/perception and 0.620/0.216→0.684/0.241 with Swin classification. Oracle classification/segmentation reaches 0.850/0.399, leaving a nonzero planning gap. Classification changes interact with the segmentation backbone, so the full gain cannot be attributed solely to verification. Re-identification experiments show fixed-threshold true positives degrade with greater distance, supporting the motivation to approach before rejecting.',implementation='Official repository/supplement discovery pending. No project code executed.',bottlenecks=[b('ieve-perception','Distance-aware verification reduces rejection errors but remains dependent on viewpoint-sensitive instance features.','Textureless objects, camera mismatch, occlusion, repeated similar instances, or inaccurate category segmentation.','Match counts are heuristic evidence and both the map and verification depend on visual perception.','PAPER EXPERIMENT: Tables 1–2 oracle perception gap and re-identification distance analysis.',['AIUTA'],'Partially addressed')],limits=['Separate supplement specifies exploration learning and collision details; review pending. Do not assume PPO for the proposed policy from the PPO baseline alone.'])

put('metaexplore',title='Meta-Explore: Exploratory Hierarchical Vision-and-Language Navigation Using Scene Object Spectrum Grounding',authors=['Minyoung Hwang','Jaeyeon Jeong','Minsoo Kim','Yoonseon Oh','Songhwai Oh'],year=2023,venue='CVPR 2023',pages=['3–8'],problem='Recover from an incorrect high-level route by selecting a useful local destination in an online topological graph. The method starts from a DUET-style graph navigator and uses object-layout grounding to choose recovery goals.',method='A graph cross-modal encoder feeds navigation, object grounding, progress, and mode heads. The paper calls ordinary goal-directed navigation exploration and corrective graph traversal exploitation. Mode supervision labels detours off the shortest route; a threshold of 0.5 activates recovery. Progress predicts 1 minus current/start goal distance with squared loss. A correlation regularizer, action imitation, and object grounding accompany actor-critic fine-tuning. Scene object spectra are built from category-specific binary bounding-box masks: log magnitude of a 2-D Fourier transform is vertically averaged and normalized into a K by eta representation. An instruction-derived spectrum uses an object list and average box width. Candidate recovery destinations are scored by spectrum similarity along a corrected shortest initial-to-candidate path, and the agent physically traverses the graph shortest path to the selected frontier. No future-view image is generated by this method.',novelty='Adds instruction-conditioned object-spectrum recovery goals and learned switching to a DUET-based hierarchical agent. Spectrum grounding represents object arrangements beyond an unordered object bag, but magnitude spectra discard translation phase, and the instruction-to-object conversion does not preserve all relational language.',results='PAPER EXPERIMENT: Table 1 R2R unseen DUET SR/SPL 72/60→72/62; test 69/59→71/61. Table 3 oracle goal choice gives 75.95/62.53, spectrum choice 71.78/61.68, and homing 71.65/60.60: R2R gains over homing are modest. SOON test SR/SPL improves 33.4/21.4→39.1/25.8, while object-grounded FSPL falls 4.2→4.0. The authors attribute weaker REVERIE recovery to many categories that are not distinctive or are replaceable. Higher success is evidence for partial recovery improvement, not a calibrated error detector or proof of semantic route correction.',implementation='Official source and separate supplement discovery pending. Continuous-environment experiments are referenced but not yet reviewed in the main supplied PDF.',bottlenecks=[b('meta-spectrum','Object-spectrum recovery cannot uniquely determine the intended route when relational information or category distinctiveness matters.','Repeated objects, generic landmarks, direction-sensitive instructions, or false detections.','Object lists omit some language relations and Fourier magnitude removes translation phase; mode labels operationalize shortest-path detours rather than all instruction violations.','AUTHOR ACKNOWLEDGEMENT: REVERIE discussion; DEDUCTION from spectral representation and labels.',['NavNuances','M-Track','GELA'],'Partially addressed')],limits=['Supplementary CE results, exact loss implementation, and the main-text SPL notation require source checking. No benchmark executed.'])

put('vsi_bench',title='Thinking in Space: How Multimodal Large Language Models See, Remember, and Recall Spaces',authors=['Jihan Yang','Shusheng Yang','Anjali W. Gupta','Rilyn Han','Li Fei-Fei','Saining Xie'],year=2025,venue='CVPR 2025',pages=['4–8'],problem='Evaluate spatial reasoning from indoor video, including counting, dimensions, distances, directions, route planning, and appearance order. This is offline video question answering, not an interactive navigation policy evaluation.',method='VSI-Bench derives questions from ScanNet, ScanNet++, and ARKit scene reconstructions and videos. Most questions use 3-D annotations and templates, with human route-planning annotations and iterative human filtering. Four tasks require numeric answers (object count, absolute distance, object size, room size); four use multiple-choice answers (relative distance, relative direction, route planning, appearance order). Numeric scoring averages relative-error thresholds from 0.5 through 0.95; multiple-choice scoring extracts answer letters/text. Fifteen pretrained models are evaluated zero-shot with greedy decoding. Additional controlled prompt experiments use CoT, tree-style reasoning, and five-sample self-consistency. Grid-map prompting asks models to place objects in a 10 by 10 or 20 by 20 map; supplied ground-truth maps separate perception/memory errors from map-use errors.',novelty='Provides a video spatial reasoning benchmark and tests whether explicit language reasoning or spatial representations improve answers. The map intervention is stronger evidence about usable spatial information than an attention picture, but the generated map is an external prediction rather than direct measurement of a model’s latent world state.',results='PAPER EXPERIMENT: Table 1 full benchmark Gemini-1.5-Pro 45.4 and GPT-4o 34.0, compared with a frequent-answer baseline 34.0; seven of twelve open models fall below that baseline. Human 79.2 is measured on a 400-question subset (50 per task), where Gemini scores 48.8, so human/full-set comparisons must preserve denominators. On 163 wrong subset answers, a self-explanation-based audit attributes 71% to spatial issues; this categorization is not a causal latent-mechanism test. CoT/tree prompting decreases mean performance by roughly four points in tested configurations and self-consistency by 1.1, without establishing that language reasoning always harms navigation. Table 3 relative-distance accuracy 46 baseline→56 predicted 10-grid→66 ground-truth 10-grid; a ground-truth 20-grid reaches 78 while predicted 20-grid is 54. Map quality, resolution, and downstream reasoning therefore interact.',implementation='Official benchmark repository and appendix discovery pending. No model inference executed.',bottlenecks=[b('vsi-spatial','Generated spatial representations are inaccurate enough to limit the benefit of explicit map reasoning.','Distant object pairs, high-resolution maps, and geometric questions beyond local adjacency.','Perception, temporal memory, and spatial reconstruction errors enter the map before reasoning.','PAPER EXPERIMENT: Table 3 and local-versus-distant map analysis.',['OmniAgent'],'Partially addressed'),b('vsi-transfer','Offline spatial QA accuracy does not establish closed-loop navigation reliability.','A policy must select views, execute movements, and recover from observation or action errors.','The benchmark supplies a fixed video and evaluates an answer rather than interactive control.','DEDUCTION from benchmark protocol.',['EmbodiedQA','IQA','VLN-MME'],'Uncertain because evidence is insufficient','Evaluation')],limits=['Initial dataset construction pages, embedded/separate appendix and evaluation code review pending. Human and model full-set numbers use different denominators.'])

render()
